package com.clinic.notification.repository;import com.clinic.notification.domain.MedicationPlan;import org.springframework.data.domain.Pageable;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.Instant;import java.util.*;public interface MedicationPlanRepository extends JpaRepository<MedicationPlan,UUID>{@Query("select m from MedicationPlan m where m.active=true and m.nextDueAt<=:now")List<MedicationPlan> due(@Param("now")Instant now,Pageable page);boolean existsByDedupeKey(String key);}
